import { codexAgent } from "niceeval/adapter";

// The built-in adapter maps Codex's JSONL transcript and file diff faithfully.
export const expressCodex = codexAgent();

// ./scripts/build-e2b-template.ts
import { Template } from "e2b";
import {
  e2bCodingAgentTemplate,
  verifyE2BNodeToolContract,
} from "niceeval/sandbox/e2b-template";

